$(document).ready(function(){$("#license_input_button").click(function(){var e=$("#license_input_text").val();""!==e&&$.post(OC.generateUrl("/license/license"),{licenseString:e}).done(function(){location.reload()})}),$("#license_remove_button").click(function(){$.ajax({url:OC.generateUrl("/license/license"),type:"DELETE"}).done(function(){location.reload()})})});